/**
 * State - Key-value perception store with timestamps
 *
 * Stores AI perception data written by Sensors and read by Intents.
 * Each key tracks when it was last updated for staleness detection.
 *
 * **Usage**
 *
 * ```js
 * // Sensor writes perception data
 * state.set('targetVisible', true);
 * state.set('targetPosition', { x: 10, y: 0, z: 5 });
 *
 * // Intent reads perception data
 * const visible = state.get('targetVisible', false);
 * const pos = state.get('targetPosition');
 *
 * // Check staleness
 * const age = state.getAge('targetVisible'); // seconds since update
 * ```
 *
 * @module @three-blocks/pro/ai/State
 * @class State
 * @short Key-value perception store with timestamps
 * @category AI
 * @tags AI, Perception, State
 */
export class State {
    /**
     * @type {Map<string, any>}
     * @private
     */
    private _data;
    /**
     * @type {Map<string, number>}
     * @private
     */
    private _timestamps;
    /**
     * Current time reference for age calculations.
     * @type {number}
     * @private
     */
    private _currentTime;
    /**
     * Set a value in the state.
     *
     * @param {string} key - The key to set.
     * @param {any} value - The value to store.
     * @returns {State} This instance for chaining.
     */
    set(key: string, value: any): State;
    /**
     * Set multiple values at once.
     *
     * @param {Object} entries - Object with key-value pairs to set.
     * @returns {State} This instance for chaining.
     */
    setMultiple(entries: any): State;
    /**
     * Get a value from the state.
     *
     * @param {string} key - The key to get.
     * @param {any} [defaultValue=null] - Value to return if key doesn't exist.
     * @returns {any} The stored value or default.
     */
    get(key: string, defaultValue?: any): any;
    /**
     * Check if a key exists in the state.
     *
     * @param {string} key - The key to check.
     * @returns {boolean} True if the key exists.
     */
    has(key: string): boolean;
    /**
     * Get the age of a value in seconds.
     *
     * @param {string} key - The key to check.
     * @returns {number} Seconds since last update, or Infinity if never set.
     */
    getAge(key: string): number;
    /**
     * Delete a key from the state.
     *
     * @param {string} key - The key to delete.
     * @returns {boolean} True if the key existed and was deleted.
     */
    delete(key: string): boolean;
    /**
     * Clear all state data.
     *
     * @returns {State} This instance for chaining.
     */
    clear(): State;
    /**
     * Update the internal time reference.
     * Called each frame before sensors run.
     *
     * @param {number} delta - Time delta in seconds.
     * @returns {State} This instance for chaining.
     */
    update(delta: number): State;
    /**
     * Get all keys in the state.
     *
     * @returns {string[]} Array of all keys.
     */
    keys(): string[];
    /**
     * Get the number of entries in the state.
     *
     * @returns {number} Number of entries.
     */
    get size(): number;
}
